  "canvases": [
    {
      "context": "subscriptions",
      "name": "Subscriptions",
      "purpose": "Subscriptions decides which meals each household receives each week and keeps the standing order alive: it opens, pauses and cancels subscriptions and locks a week's choice before the cutoff, so that households keep choosing (G1). It does not charge the card (billing) or pack the box (fulfilment).",
      "strategic_classification": {
        "domain": "core",
        "business_model": "revenue-generator",
        "evolution": "custom"
      },
      "domain_roles": [
        "execution-context"
      ],
      "domain_roles_rationale": "Execution context: it owns the subscription aggregate and takes the household's commands directly; the weekly cutoff is enforced here, not downstream.",
      "inbound": [
        {
          "collaborator": "subscriber",
          "relationship": "user-interaction",
          "messages": [
            {
              "id": "choose-meals",
              "kind": "command",
              "name": "Choose Meals",
              "payload": [
                "subscriptionId",
                "week",
                "recipeIds"
              ],
              "delivery": "sync",
              "via": "http",
              "sync": true
            },
            {
              "id": "start-subscription",
              "kind": "command",
              "name": "Start Subscription"
            }
          ]
        }
      ],
      "outbound": [
        {
          "collaborator": "billing",
          "relationship": "customer-supplier",
          "messages": [
            {
              "id": "meals-chosen",
              "kind": "event",
              "name": "Meals Chosen",
              "payload": [
                "subscriptionId",
                "week",
                "recipeIds"
              ],
              "delivery": "at-least-once",
              "via": "in-process",
              "sync": false
            }
          ]
        }
      ],
      "ubiquitous_language": [
        {
          "term": "Subscription",
          "definition": "a customer's standing weekly order",
          "avoid": [
            "plan",
            "membership"
          ]
        },
        {
          "term": "Box",
          "definition": "…"
        }
      ],
      "business_decisions": [
        "A week can be chosen once; a second choice for the same week is rejected",
        "Choices lock at the weekly cutoff; after it, default meals are assigned"
      ],
      "assumptions": [
        "[define A1] Fixture: metrics are illustrative targets"
      ],
      "verification_metrics": [
        "Business (G1): active subscriptions grow month on month; weekly choice completed by >90% of active households before cutoff",
        "Boundary: zero cross-module reads of subscription tables from billing/fulfilment (CI check)"
      ],
      "open_questions": [
        "[connect CC1 — coupling, medium] Fulfilment needs recipe details from subscriptions"
      ],
      "canvas_path": "ddd/07-define/subscriptions/bounded-context-canvas.md",
      "subdomains": [
        "subscriptions"
      ],
      "owning_team": "solo",
      "deployable": "app",
      "implementation_pattern": "domain-model"
    },
    {
      "context": "billing",
      "name": "Billing",
      "purpose": "Billing takes the money for a chosen week: whenever meals are chosen it charges the household's card through Stripe and tells the rest of the system the week is paid. It owns no product rules — a failed charge is reported back to subscriptions, which decides what to do.",
      "strategic_classification": {
        "domain": "generic",
        "business_model": "cost-reducer",
        "evolution": "commodity"
      },
      "domain_roles": [
        "execution-context"
      ],
      "domain_roles_rationale": "Execution context around a bought capability: it reacts to meals-chosen and executes the charge through the Stripe ACL; no model of its own beyond the charge record.",
      "inbound": [
        {
          "collaborator": "subscriptions",
          "relationship": "customer-supplier",
          "messages": [
            {
              "id": "meals-chosen",
              "kind": "event",
              "name": "Meals Chosen",
              "payload": [
                "subscriptionId",
                "week",
                "recipeIds"
              ],
              "delivery": "at-least-once",
              "via": "in-process",
              "sync": false
            }
          ]
        }
      ],
      "outbound": [
        {
          "collaborator": "fulfilment",
          "relationship": "published-language",
          "messages": [
            {
              "id": "week-charged",
              "kind": "event",
              "name": "Week Charged",
              "payload": [
                "subscriptionId",
                "week"
              ],
              "delivery": "at-least-once",
              "via": "message-bus",
              "sync": false
            }
          ]
        },
        {
          "collaborator": "stripe",
          "relationship": "anticorruption-layer",
          "messages": [
            {
              "id": "charge-card",
              "kind": "command",
              "name": "Charge Card",
              "payload": [
                "subscriptionId",
                "week",
                "amount",
                "currency"
              ],
              "delivery": "sync",
              "via": "http",
              "sync": true
            }
          ]
        }
      ],
      "ubiquitous_language": [
        {
          "term": "Box",
          "definition": "…"
        }
      ],
      "business_decisions": [
        "A week is charged exactly once, on meals-chosen; retries are idempotent on subscriptionId+week",
        "A declined card pauses the subscription and releases the week"
      ],
      "assumptions": [
        "[define A1] Fixture: metrics are illustrative targets"
      ],
      "verification_metrics": [
        "Business: failed charges retried and resolved within 24h for >95% of weeks",
        "Boundary: every Stripe call goes through the PaymentGateway ACL (fitness test)"
      ],
      "open_questions": [
        "[discover H1 near week-charged — unclear] What happens if payment fails after meals are chosen?"
      ],
      "canvas_path": "ddd/07-define/billing/bounded-context-canvas.md",
      "subdomains": [
        "billing"
      ],
      "owning_team": "solo",
      "deployable": "app",
      "implementation_pattern": "transaction-script"
    },
    {
      "context": "fulfilment",
      "name": "Fulfilment",
      "purpose": "Fulfilment turns a paid week into a physical box: it builds the picking list, packs the box in the warehouse and hands it to the courier with tracking, so the household gets what it chose. It never queries subscriptions; everything it needs arrives on week-charged.",
      "strategic_classification": {
        "domain": "supporting",
        "business_model": "cost-reducer",
        "evolution": "custom"
      },
      "domain_roles": [
        "execution-context"
      ],
      "domain_roles_rationale": "Execution context: packers act on it directly and it owns the physical box's lifecycle; it consumes week-charged and never queries subscriptions.",
      "inbound": [
        {
          "collaborator": "billing",
          "relationship": "published-language",
          "messages": [
            {
              "id": "week-charged",
              "kind": "event",
              "name": "Week Charged",
              "payload": [
                "subscriptionId",
                "week"
              ],
              "delivery": "at-least-once",
              "via": "message-bus",
              "sync": false
            }
          ]
        },
        {
          "collaborator": "packer",
          "relationship": "user-interaction",
          "messages": [
            {
              "id": "pack-box",
              "kind": "command",
              "name": "Pack Box"
            },
            {
              "id": "ship-box",
              "kind": "command",
              "name": "Ship Box"
            }
          ]
        }
      ],
      "outbound": [],
      "ubiquitous_language": [
        {
          "term": "Box",
          "definition": "…"
        }
      ],
      "business_decisions": [
        "A box is packed only for a charged week",
        "A box is shipped only after it is packed; tracking is recorded on shipment"
      ],
      "assumptions": [
        "[define A1] Fixture: metrics are illustrative targets"
      ],
      "verification_metrics": [
        "Business: boxes packed within 12h of week-charged for >99% of weeks; mis-picks <0.5%",
        "Boundary: fulfilment reads recipe/picking data only from the week-charged payload or its own projection"
      ],
      "open_questions": [
        "[connect CC1 — coupling, medium] Fulfilment needs recipe details from subscriptions"
      ],
      "canvas_path": "ddd/07-define/fulfilment/bounded-context-canvas.md",
      "subdomains": [
        "fulfilment"
      ],
      "owning_team": "solo",
      "deployable": "warehouse",
      "implementation_pattern": "active-record"
    }
  ],
